def solve(s=None):
    """Run‑length encode *s*.
    *s* may be a string, bytes, or any iterable of hashable items.
    If *s* is ``None`` or empty, returns an empty list.
    The result is a list of [item, count] pairs where *item* is the original
    element (converted to ``str`` for bytes to keep behaviour consistent with
    typical string handling).
    """
    # Treat None as empty input
    if s is None:
        return []
    # If it's a bytes object, interpret each byte as a character using chr
    if isinstance(s, (bytes, bytearray)):
        seq = [chr(b) for b in s]
    else:
        # For strings, keep as is (iterating yields characters)
        # For other iterables, convert to list to allow indexing
        try:
            # strings are iterable, but we want them as sequence of characters
            if isinstance(s, str):
                seq = list(s)
            else:
                seq = list(s)
        except TypeError:
            # Not iterable, treat as single element
            seq = [s]
    if not seq:
        return []
    res = []
    cur = seq[0]
    cnt = 1
    for item in seq[1:]:
        if item == cur:
            cnt += 1
        else:
            res.append([cur, cnt])
            cur = item
            cnt = 1
    res.append([cur, cnt])
    return res

